#!/usr/bin/env Rscript
# =============================================================================
# compare_synthetic.R
#
# Runs phenofit on synthetic NDVI time series generated by
# examples/generate_synthetic_ndvi.py and saves results for comparison.
#
# Usage:
#   Rscript validation/r/compare_synthetic.R
#
# Outputs (in validation/r_results/):
#   r_gof.csv       - GOF metrics (RMSE, R2) per scenario × method
#   r_fitted.csv    - dense fitted values (tout) per scenario × method
#   r_pheno.csv     - phenology dates per scenario × method
# =============================================================================

library(phenofit)

IN_CSV  <- "validation/synthetic_ndvi.csv"
OUT_DIR <- "validation/r_results"
dir.create(OUT_DIR, showWarnings = FALSE, recursive = TRUE)

if (!file.exists(IN_CSV)) {
  stop(paste("Input CSV not found:", IN_CSV,
             "\nRun: python examples/generate_synthetic_ndvi.py"))
}

df       <- read.csv(IN_CSV)
scenarios <- unique(df$scenario)
methods   <- c("Beck", "Elmore", "Zhang", "AG", "Gu")

gof_rows    <- list()
fitted_rows <- list()
pheno_rows  <- list()

for (sc in scenarios) {
  cat(sprintf("\n=== Scenario: %s ===\n", sc))
  sub <- df[df$scenario == sc, ]
  t   <- sub$t
  y   <- sub$y
  w   <- sub$w
  tout <- t   # same grid

  tryCatch({
    fit <- curvefit(y, t = t, tout = tout, methods = methods, w = w)

    # ---- GOF ----
    gof <- tryCatch(as.data.frame(get_GOF(fit)), error = function(e) NULL)
    if (!is.null(gof)) {
      gof$scenario <- sc
      gof_rows[[length(gof_rows) + 1]] <- gof
    }

    # ---- Fitted values ----
    for (m in methods) {
      mod <- fit$model[[m]]
      if (is.null(mod)) next
      zs <- mod$zs
      z  <- if (is.list(zs)) zs[[length(zs)]] else zs
      if (length(z) == length(tout)) {
        fitted_rows[[length(fitted_rows) + 1]] <- data.frame(
          scenario = sc, method = m, t = tout, fitted = z
        )
      }
    }

    # ---- Phenology (Beck curve only — most stable) ----
    fit_beck <- curvefit(y, t = t, tout = tout, methods = "Beck", w = w)
    pheno    <- tryCatch(get_pheno(fit_beck), error = function(e) NULL)
    if (!is.null(pheno)) {
      row_data <- list(scenario = sc)

      # TRS
      for (trs_key in c("TRS2", "TRS5")) {
        trs_obj <- pheno[[trs_key]]
        if (!is.null(trs_obj)) {
          row_data[[paste0(trs_key, ".SOS")]] <- as.numeric(trs_obj["sos"])
          row_data[[paste0(trs_key, ".EOS")]] <- as.numeric(trs_obj["eos"])
        }
      }

      # DER
      der <- pheno$DER
      if (!is.null(der)) {
        row_data[["DER.SOS"]] <- as.numeric(der["sos"])
        row_data[["DER.POS"]] <- as.numeric(der["pos"])
        row_data[["DER.EOS"]] <- as.numeric(der["eos"])
      }

      pheno_rows[[length(pheno_rows) + 1]] <- as.data.frame(row_data)
    }

  }, error = function(e) {
    cat(sprintf("  ERROR: %s\n", conditionMessage(e)))
  })
}

# ---- Write outputs ----
if (length(gof_rows) > 0) {
  gof_df <- do.call(rbind, lapply(gof_rows, function(x) {
    # get_GOF already provides a 'meth' column with method names.
    # Only fall back to rownames when meth is absent or numeric.
    if (!"meth" %in% names(x)) {
      x$meth <- rownames(x)
    } else if (!is.character(x$meth) || all(grepl("^[0-9]+$", x$meth))) {
      x$meth <- rownames(x)
    }
    rownames(x) <- NULL
    x
  }))
  write.csv(gof_df, file.path(OUT_DIR, "r_gof.csv"), row.names = FALSE)
  cat("\nr_gof.csv written\n")
}

if (length(fitted_rows) > 0) {
  fitted_df <- do.call(rbind, fitted_rows)
  write.csv(fitted_df, file.path(OUT_DIR, "r_fitted.csv"), row.names = FALSE)
  cat("r_fitted.csv written\n")
}

if (length(pheno_rows) > 0) {
  pheno_df <- do.call(rbind, lapply(pheno_rows, function(x) {
    # Fill missing columns with NA
    x[setdiff(c("scenario","TRS2.SOS","TRS2.EOS","TRS5.SOS","TRS5.EOS",
                "DER.SOS","DER.POS","DER.EOS"), names(x))] <- NA
    x
  }))
  write.csv(pheno_df, file.path(OUT_DIR, "r_pheno.csv"), row.names = FALSE)
  cat("r_pheno.csv written\n")
}

cat(sprintf("\nDone. Results in %s/\n", OUT_DIR))
